const output = $json.output;
const allItems = [];

// Long form'ları ekle
if (output.long_form) {
  output.long_form.forEach((item) => {
    allItems.push({
      json: {
        tarih: item.publish_date,
        baslik: item.title,
        aciklama: item.description,
        format: 'long',
        'ana-tema': item.prompt,
        'sahne-prompt': '',
        durum: 'planlandı'
      }
    });
  });
}

// Shorts'ları ekle
if (output.shorts) {
  output.shorts.forEach((item) => {
    allItems.push({
      json: {
        tarih: item.publish_date,
        baslik: item.title,
        aciklama: item.description,
        format: 'short',
        'ana-tema': item.prompt,
        'sahne-prompt': '',
        durum: 'planlandı'
      }
    });
  });
}

return allItems;
